import {VoiceTrial,voiceError,parseSpeech} from './voice.js';
const $=id=>document.getElementById(id),Ctor=window.SpeechRecognition||window.webkitSpeechRecognition;
$('capability').textContent=Ctor?'El navegador expone reconocimiento de voz. Esto no demuestra que su servicio funcione.':'Voz no disponible: el navegador no expone reconocimiento. El formulario sigue disponible.';
$('mic').disabled=!Ctor;
const session=new VoiceTrial(()=>new Ctor(),s=>{const active=['starting','listening','stopping','result'].includes(s.phase)&&session.active;$('mic').disabled=!Ctor||active;$('stop').disabled=!active;$('status').textContent=s.phase==='error'?(s.error==='unsupported'?'Voz no disponible en este navegador.':voiceError(s.error)):({starting:'Solicitando reconocimiento…',listening:'Escuchando en español. Puedes detenerlo.',stopping:'Deteniendo la escucha…',result:'Escuchando en español. Texto recibido; puedes continuar o pulsar Detener.',review:'Escucha terminada. Revisa lo entendido; no se ha guardado nada.',ended:'Escucha terminada sin texto. El formulario sigue disponible.',cancelled:'Escucha cancelada. No se ha guardado nada.'}[s.phase]);if(['review','ended'].includes(s.phase))$('status').textContent=({user:'Escucha detenida por ti.',limit:'Escucha detenida por el límite de dos minutos.',browser:'El navegador ha terminado la escucha.'}[s.endReason]||'Escucha terminada.')+' Revisa lo entendido; no se ha guardado nada.';$('heard').value=s.text;$('apply').disabled=!s.text||active;$('diagnostic').textContent=JSON.stringify({recognitionExposed:!!Ctor,secureContext:window.isSecureContext,online:navigator.onLine,embedded:window.top!==window.self,language:'es-ES',phase:s.phase,endReason:s.endReason||'',elapsedMs:s.elapsedMs??null,continuousRequested:true,error:s.error||'',localRecognitionAPI:typeof Ctor?.available==='function'},null,2);});
$('mic').onclick=()=>session.start();$('stop').onclick=()=>session.stop();
$('apply').onclick=()=>{const p=parseSpeech($('heard').value);$('name').value=p.name;$('qty').value=p.qty;$('unit').value=p.unit;$('date').value=p.date;$('review-warning').textContent=p.warnings.join(' ')||'Revisa nombre, cantidad, unidad, fecha y tipo. No se ha guardado nada.';$('name').focus();};
$('form').onsubmit=e=>{e.preventDefault();const qty=Number($('qty').value);if(!$('unit').value){$('review-warning').textContent='Elige la unidad: no se deduce del nombre del alimento.';return;}if(!$('name').value.trim()||!(qty>0)||($('unit').value==='ud'&&!Number.isInteger(qty))){$('review-warning').textContent='Revisa nombre y cantidad. ud representa piezas enteras, sin redondeo.';return;}if($('date').value&&!$('type').value){$('review-warning').textContent='Elige el tipo de la fecha o déjala vacía.';return;}$('review-warning').textContent='Datos de prueba revisados: '+$('name').value.trim()+', '+qty+' '+$('unit').value+', '+($('date').value||'sin fecha')+'. No se guardan en ningún hogar.';};
window.addEventListener('pagehide',()=>session.cancel());document.addEventListener('visibilitychange',()=>{if(document.hidden)session.cancel();});
